   128  PJ_OBS proj_trans_obs (PJ *P, enum proj_direction direction, PJ_OBS obs) {
   129      if (0==P)
   130          return obs;
   131
   132      switch (direction) {
   133          case PJ_FWD:
   134              return pj_fwdobs (obs, P);
   135          case PJ_INV:
   136              return  pj_invobs (obs, P);
   137          case PJ_IDENT:
   138              return obs;
   139          default:
   140              break;
   141      }
   142
   143      proj_errno_set (P, EINVAL);
   144      return proj_obs_error ();
   145  }
